// ===== rk_el_v1: CSS sluoksnis puslapiams, perkeltiems i tikrus Elementor blokus (.rk-el) =====
function rk_el_prefix_css($css) {
    $css = preg_replace('#/\*.*?\*/#s', '', $css);
    $out = ''; $i = 0; $len = strlen($css);
    $map = array('/(^|[\s>+~,])ul(?=[\s.:>,{\[]|$)/' => '$1.el-ul', '/(^|[\s>+~,])li(?=[\s.:>,{\[]|$)/' => '$1.el-li', '/(^|[\s>+~,])div(?=[\s.:>,{\[]|$)/' => '$1.el-div');
    $fix = function ($sel) use ($map) {
        $sel = trim($sel);
        if ($sel === '' || $sel === ':root' || strpos($sel, 'html') === 0) return $sel;
        $sel = str_replace('>', ' ', $sel);
        foreach ($map as $re => $rep) $sel = preg_replace($re, $rep, $sel);
        if (preg_match('/^body[^\s]*\s+(.*)$/', $sel, $m)) return preg_replace('/^(body[^\s]*)\s+/', '$1 .rk-el ', $sel);
        if (preg_match('/^body/', $sel)) return $sel . ' .rk-el';
        return '.rk-el ' . $sel;
    };
    $process = function ($block) use ($fix) {
        $o = '';
        preg_match_all('/([^{}]+)\{([^{}]*)\}/s', $block, $mm, PREG_SET_ORDER);
        foreach ($mm as $r) {
            $sels = array_map($fix, explode(',', $r[1]));
            $decl = trim($r[2]);
            if (preg_match('/display\s*:\s*(inline-)?flex/', $decl) && !preg_match('/flex-direction/', $decl)) $decl .= ';flex-direction:row';
            $o .= implode(',', $sels) . '{' . $decl . '}';
        }
        return $o;
    };
    // @media blokai
    $pos = 0;
    while (preg_match('/@media[^{]*\{/', $css, $m, PREG_OFFSET_CAPTURE, $pos)) {
        $start = $m[0][1]; $out .= $process(substr($css, $pos, $start - $pos));
        $depth = 1; $j = $start + strlen($m[0][0]);
        while ($j < $len && $depth) { if ($css[$j] === '{') $depth++; elseif ($css[$j] === '}') $depth--; $j++; }
        $out .= $m[0][0] . $process(substr($css, $start + strlen($m[0][0]), $j - 1 - ($start + strlen($m[0][0])))) . '}';
        $pos = $j;
    }
    $out .= $process(substr($css, $pos));
    return $out;
}
add_action('wp_head', function () {
    if (is_admin()) return;
    $post_id = get_queried_object_id();
    $data = $post_id ? get_post_meta($post_id, '_elementor_data', true) : '';
    if (!$data || strpos($data, '"rk-el"') === false) return;
    $css = get_transient('rk_el_css');
    if ($css === false) {
        $shared = get_transient('rk_shared_css');
        if ($shared === false) { $arr = json_decode(get_post_meta(15, '_elementor_data', true), true); $h = ''; array_walk_recursive($arr, function ($v, $k) use (&$h) { if ($k === 'html' && is_string($v) && strlen($v) > strlen($h)) $h = $v; }); preg_match('/<style>(.*?)<\/style>/s', $h, $m); $shared = isset($m[1]) ? $m[1] : ''; }
        $css = rk_el_prefix_css($shared . (defined('RK_SKIN_CSS') ? RK_SKIN_CSS : '') . (defined('RK_PC_CSS') ? RK_PC_CSS : '') . (defined('RK_FIX_CSS') ? RK_FIX_CSS : ''));
        set_transient('rk_el_css', $css, DAY_IN_SECONDS);
    }
    $reset = '.rk-el .e-con{--padding-top:0;--padding-right:0;--padding-bottom:0;--padding-left:0;--margin-top:0;--margin-bottom:0;max-width:none;min-height:0}'
        . '.rk-el .elementor-widget:not(:last-child){margin-block-end:0}.rk-el .e-con>.elementor-widget,.rk-el .e-con>.e-con{width:auto;max-width:100%}.rk-el .e-con[class*=el-]{--align-items:stretch}'
        . '.rk-el .elementor-widget-heading .elementor-heading-title{margin:0;color:inherit}.rk-el .elementor-heading-title a{color:inherit;text-decoration:none}'
        . '.rk-el .elementor-widget-text-editor{font-size:inherit;color:inherit}.rk-el .elementor-widget-text-editor p:last-child{margin-bottom:0}.rk-el .elementor-widget-text-editor p:first-child{margin-top:0}'
        . '.rk-el .el-inl{flex-direction:row;flex-wrap:wrap;align-items:center;gap:10px}.rk-el .el-li{list-style:none}.rk-el .el-details{width:100%}.rk-el .rkp-faq .elementor-widget-text-editor{width:100%}'
        . '.rk-el .el-p,.rk-el .el-details,.rk-el .rkp-two .el-div,.rk-el .grid4 .wcard .el-div,.rk-el .grid5 .wcard .el-div{width:100%}';
    echo '<style id="rk-el">' . $reset . $css . '</style>';
}, 103);
